  const metaPkg = JSON.parse(fs.readFileSync(metaPkgPath, "utf-8"));
  metaDeps = {
    ...(metaPkg.dependencies || {}),
    ...(metaPkg.optionalDependencies || {}),
    ...(metaPkg.peerDependencies || {}),
  };
}

