const fs = require("fs");
const path = require("path");

const root = process.cwd();

// Find workspace packages matching pnpm-workspace patterns
const patterns = [
  "package.json",
  "docs/package.json",
  "packages/*/package.json",
  "formats/*/package.json",
  "platforms/*/package.json",
  "renderers/*/package.json",
  "bundlers/*/package.json",
  "design/*/package.json",
  "ai/*/package.json",
  "plugins/pantoken/*/package.json",
  "plugins/postcss/*/package.json",
  "plugins/typedoc/*/package.json",
  "plugins/vite/*/package.json",
  "tools/*/package.json"
];

function globMatch(pattern, relPath) {
  const pParts = pattern.split("/");
  const rParts = relPath.split("/");
  if (pParts.length !== rParts.length) return false;
  for (let i = 0; i < pParts.length; i++) {
    if (pParts[i] === "*") continue;
    if (pParts[i] !== rParts[i]) return false;
  }
  return true;
}

function findPackageJsons(dir, list = []) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if ([".git", "node_modules", "dist", ".worktrees", "templates", ".dev", ".turbo", ".vite", ".vitepress", "coverage"].includes(entry.name)) continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      findPackageJsons(fullPath, list);
    } else if (entry.isFile() && entry.name === "package.json") {
      list.push(fullPath);
    }
  }
  return list;
}

const allPkgs = findPackageJsons(root);
const metaPkg = JSON.parse(fs.readFileSync(path.join(root, "packages/pantoken/package.json"), "utf-8"));
const metaDeps = metaPkg.dependencies || {};

const results = allPkgs.map(f => {
  const relPath = path.relative(root, f);
  const json = JSON.parse(fs.readFileSync(f, "utf-8"));
  return {
    name: json.name || "(no name)",
    path: relPath,
    private: Boolean(json.private),
    pantoken: json.pantoken,
    hasPantoken: Boolean(json.pantoken),
    pantokenKey: json.pantoken?.key || null,
    inMetaDeps: Boolean(metaDeps[json.name]),
  };
}).sort((a, b) => a.path.localeCompare(b.path));

console.log(JSON.stringify(results, null, 2));
